-- Dolibarr AI Demo large historical dataset.
-- Target database: dolibarr; execute manually after reviewing the preflight.
-- This script INSERTs rows in reserved ID ranges and performs one scoped stock UPDATE for those new rows.
-- Dataset profile: 12 months, 240 sales orders, 720 order lines, 96 supplier orders,
-- about 184 supplier-order lines, about 75 receptions, 150 reception lines, 432 invoice lines,
-- hundreds of document links, and hundreds of stock movements.
-- Normal data is the majority; 8 sales orders and 4 products are deliberate anomalies.
-- This file writes only Dolibarr source business tables. It never writes the
-- llx_ai_dashboard_* tables; Hermes must infer and write those results later.
-- Run once. If a preflight count is non-zero, stop and change the reserved ranges.

SELECT 'reserved_id_conflicts' AS check_name, COUNT(*) AS conflict_count FROM (
    SELECT rowid FROM llx_societe WHERE rowid BETWEEN 120001 AND 120104
    UNION ALL SELECT rowid FROM llx_entrepot WHERE rowid BETWEEN 120201 AND 120203
    UNION ALL SELECT rowid FROM llx_product WHERE rowid BETWEEN 120301 AND 120318
    UNION ALL SELECT rowid FROM llx_product_fournisseur_price WHERE rowid BETWEEN 120401 AND 120418
    UNION ALL SELECT rowid FROM llx_product_stock WHERE rowid BETWEEN 120501 AND 120518
    UNION ALL SELECT rowid FROM llx_stock_mouvement WHERE rowid BETWEEN 120601 AND 120999
    UNION ALL SELECT rowid FROM llx_commande_fournisseur WHERE rowid BETWEEN 121001 AND 121096
    UNION ALL SELECT rowid FROM llx_commande_fournisseurdet WHERE rowid BETWEEN 121201 AND 121384
    UNION ALL SELECT rowid FROM llx_reception WHERE rowid BETWEEN 121501 AND 121577
    UNION ALL SELECT rowid FROM llx_receptiondet_batch WHERE rowid BETWEEN 121701 AND 121854
    UNION ALL SELECT rowid FROM llx_commande WHERE rowid BETWEEN 122001 AND 122240
    UNION ALL SELECT rowid FROM llx_commandedet WHERE rowid BETWEEN 122301 AND 123020
    UNION ALL SELECT rowid FROM llx_facture WHERE rowid BETWEEN 123001 AND 123144
    UNION ALL SELECT rowid FROM llx_facturedet WHERE rowid BETWEEN 123301 AND 123732
    UNION ALL SELECT rowid FROM llx_element_element WHERE rowid BETWEEN 124001 AND 124400
) AS conflicts;

START TRANSACTION;
UPDATE llx_product SET stock = CASE rowid WHEN 120301 THEN 34 WHEN 120302 THEN 101 WHEN 120303 THEN 102 WHEN 120304 THEN 181 WHEN 120305 THEN 102 WHEN 120306 THEN 103 WHEN 120307 THEN 34 WHEN 120308 THEN 183 WHEN 120309 THEN 104 WHEN 120310 THEN 183 WHEN 120311 THEN 184 WHEN 120312 THEN 185 WHEN 120313 THEN 524 WHEN 120314 THEN 524 WHEN 120315 THEN 186 WHEN 120316 THEN 265 WHEN 120317 THEN 186 WHEN 120318 THEN 187 END WHERE rowid BETWEEN 120301 AND 120318;
COMMIT;

-- Postflight counts and demo views.
SELECT 'AIH products' AS dataset, COUNT(*) AS row_count FROM llx_product WHERE ref LIKE 'AIH-%'
UNION ALL SELECT 'AIH sales orders', COUNT(*) FROM llx_commande WHERE ref LIKE 'AIH-SO-%'
UNION ALL SELECT 'AIH sales lines', COUNT(*) FROM llx_commandedet WHERE rowid BETWEEN 122301 AND 123020
UNION ALL SELECT 'AIH purchase orders', COUNT(*) FROM llx_commande_fournisseur WHERE ref LIKE 'AIH-PO-%'
UNION ALL SELECT 'AIH receptions', COUNT(*) FROM llx_reception WHERE ref LIKE 'AIH-REC-%'
UNION ALL SELECT 'AIH invoices', COUNT(*) FROM llx_facture WHERE ref LIKE 'AIH-INV-%';

SELECT c.ref AS risk_order, p.ref AS product_ref, cd.qty, c.date_livraison, cf.ref AS linked_purchase_order, cf.fk_statut AS purchase_status, cf.date_livraison AS purchase_due_date
FROM llx_commande AS c
JOIN llx_commandedet AS cd ON cd.fk_commande = c.rowid
JOIN llx_product AS p ON p.rowid = cd.fk_product
LEFT JOIN llx_commande_fournisseurdet AS cfd ON cfd.rowid = cd.fk_commandefourndet
LEFT JOIN llx_commande_fournisseur AS cf ON cf.rowid = cfd.fk_commande
WHERE c.ref IN ('AIH-SO-0007', 'AIH-SO-0042', 'AIH-SO-0078', 'AIH-SO-0113', 'AIH-SO-0148', 'AIH-SO-0183', 'AIH-SO-0218', 'AIH-SO-0233')
ORDER BY c.ref;

SELECT DATE_FORMAT(f.datef, '%Y-%m') AS invoice_month, ROUND(SUM(fd.total_ht), 2) AS revenue_ht, ROUND(SUM(fd.qty * fd.buy_price_ht), 2) AS cost_ht, ROUND(SUM(fd.total_ht - fd.qty * fd.buy_price_ht), 2) AS gross_profit_ht, ROUND(100 * SUM(fd.total_ht - fd.qty * fd.buy_price_ht) / NULLIF(SUM(fd.total_ht), 0), 2) AS gross_margin_pct
FROM llx_facture AS f JOIN llx_facturedet AS fd ON fd.fk_facture = f.rowid
WHERE f.ref LIKE 'AIH-INV-%' GROUP BY DATE_FORMAT(f.datef, '%Y-%m') ORDER BY invoice_month;

SELECT p.ref, p.label, ps.reel AS current_stock, p.desiredstock, p.seuil_stock_alerte, MAX(sm.datem) AS last_movement, ROUND(ps.reel * p.cost_price, 2) AS stock_value
FROM llx_product AS p JOIN llx_product_stock AS ps ON ps.fk_product = p.rowid LEFT JOIN llx_stock_mouvement AS sm ON sm.fk_product = p.rowid
WHERE p.ref LIKE 'AIH-%' GROUP BY p.rowid, p.ref, p.label, ps.reel, p.desiredstock, p.seuil_stock_alerte, p.cost_price ORDER BY stock_value DESC;
